// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: amount to send and an arbitrary unlockTime
    function testFuzz_property(uint256 amt, uint256 unlockTime) public {
        // keep amount in a reasonable range and non-zero to be admissible for Put
        amt = bound(amt, 1, 10 ether);
        // attacker will be a contract we deploy
        Attacker attacker = new Attacker(address(c));

        // fund attacker and make the attacker call Put so c will call into attacker (fallback)
        vm.deal(address(attacker), amt);

        // record previous balance as read from c public getter (initially 0)
        uint256 before = c.Acc(address(attacker)).balance;

        // have attacker perform the Put which pays ether and sets unlockTime; attacker will try reentrancy
        attacker.doPut{value: amt}(uint256(unlockTime));

        // After Put returns, correct contract should have recorded balance increased by amt
        uint256 after = c.Acc(address(attacker)).balance;

        // General invariant: after == before + amt
        assertTrue(after == before + amt);
    }
}

// Minimal adversarial re-entrant contract: its fallback attempts reentrancy into C. The reference nonReentrant_ prevents reentrancy,
// so Put will complete and the recorded balance will include the full msg.value; the buggy inverted lock may allow reentrancy to
// interfere and cause the recorded balance to differ.
contract Attacker {
    C target;
    bool reentered;
    constructor(address _t) payable {
        target = C(_t);
        reentered = false;
    }

    // called by the test to perform Put; sends ETH and sets unlockTime
    function doPut(uint256 _unlockTime) external payable {
        // forward all ETH this contract holds for the test call
        uint256 bal = address(this).balance;
        // call Put as this contract (its fallback may get invoked by target later)
        target.Put{value: bal}(_unlockTime);
    }

    // fallback will attempt a reentrant call to Collect with 0 value to try to disturb state during Put
    fallback() external payable {
        // try reentering only once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // attempt a Collect of 0 (will only succeed if lock is inverted in mutant)
            // use low-level call to ignore revert and continue
            (bool ok, ) = address(target).call(abi.encodeWithSignature("Collect(uint256)", 0));
            ok; // ignore
        }
    }
}

