pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint128 deposit, uint64 unlockDelay) public {
        // keep deposit within reasonable bounds but wide
        uint256 amount = uint256(deposit);
        vm.assume(amount > 0);
        // adversarial counterparty: deploy attacker that will try reentrancy during Put
        Attacker attacker = new Attacker(address(c));

        // give attacker some ETH to send
        vm.deal(address(attacker), amount);

        // attacker will call Put and in its fallback try to reenter Collect to manipulate balance
        attacker.attack{value: amount}(uint256(unlockDelay));

        // After Put completes, the invariant for the correct contract: recorded balance >= deposited amount
        // Read via public getter Acc(address).balance
        (, uint256 bal) = getHolder(address(attacker));
        assertTrue(bal >= amount);
    }

    // helper to read the Holder struct via public mapping getter
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance) {
        // The mapping is public: Acc(address) returns (uint256 unlockTime, uint256 balance)
        return c.Acc(a);
    }
}

// Minimal adversarial attacker: during Put's external call path it attempts reentrancy into Collect
contract Attacker {
    C public target;
    address public owner;
    constructor(address _t) payable {
        target = C(_t);
        owner = msg.sender;
    }

    // entrypoint: call Put on target with given unlock delay
    function attack(uint256 unlockDelay) external payable {
        // forward funds and call Put - use this contract as msg.sender
        target.Put{value: msg.value}(block.timestamp + unlockDelay);
    }

    // fallback triggered if target makes a call to this contract during Put/Collect
    fallback() external payable {
        // attempt reentrancy into Collect with some amount: try to drain or change recorded balance
        // Use low gas simple call to avoid breaking on mutated modifier; we don't care if it reverts
        // choose an amount: try to withdraw half of current contract balance (if any)
        uint256 want = address(this).balance / 2;
        if (want > 0) {
            // ignore revert to allow Put to continue (different modifier may make this succeed)
            try target.Collect(want) {
            } catch {
            }
        }
    }
}

