pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: deposit amount and a candidate unlockTime
    function testFuzz_property(uint256 deposit, uint256 candidateUnlock) public {
        // keep deposit in a reasonable range and non-zero so Put will be accepted
        deposit = bound(deposit, 1 wei, 10 ether);
        // candidateUnlock may be any uint256; keep wide but bounded to avoid overflow timestamps
        candidateUnlock = bound(candidateUnlock, 0, type(uint64).max);

        // deploy a reentrant attacker that will attempt to reenter Put during our single Put call
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker with deposit
        vm.deal(address(attacker), deposit);

        // attacker will call c.Put(candidateUnlock) sending deposit and attempt reentry
        // the distinguishing observable we assert: after Put completes, Acc[attacker].unlockTime >= block.timestamp
        // call from attacker
        vm.prank(address(attacker));
        attacker.callPut{value: deposit}(candidateUnlock);

        // read acc.unlockTime via the public getter: c.Acc(address).unlockTime is synthesized as a compound return
        (uint unlockTime, uint balance) = c.Acc(address(attacker));

        // The reference contract always sets unlockTime = max(_unlockTime, block.timestamp) during Put,
        // so after Put completes unlockTime >= block.timestamp. The mutated modifier allows malicious reentry
        // that can cause unlockTime < block.timestamp for some inputs; thus this assertion holds for P for all inputs
        // and will be falsified on the buggy M for some fuzzed inputs.
        assertTrue(unlockTime >= block.timestamp);
    }
}

// Minimal reentrant attacker that during its receive will attempt to reenter Put once.
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(address _target) payable {
        target = C(_target);
        reentered = false;
    }

    // entry to trigger the attack
    function callPut(uint256 _unlock) external payable {
        // call Put on target, sending ETH from this contract
        target.Put{value: msg.value}(_unlock);
    }

    // fallback will be invoked during target.Pull's external call; attempt a single reentrant Put
    fallback() external payable {
        // only attempt reentry once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // reenter with zero value but a small unlock time to try to lower stored unlockTime
            // we pass 0 to try to make stored unlockTime = block.timestamp on reentrant path or otherwise disturb state
            target.Put{value: 0}(0);
        }
    }
}

