contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters:
    // - uint256 sendValue: amount of ETH attacker will send with Put
    // - uint256 attackerInitialBalance: starting balance we give the attacker EOA so it can fund the attack
    function testFuzz_property(uint256 sendValue, uint256 attackerInitialBalance) public {
        // keep values in wide but sensible bounds
        sendValue = bound(sendValue, 1 wei, 5 ether);
        attackerInitialBalance = bound(attackerInitialBalance, sendValue, 10 ether);

        // deploy a reentrant attacker that will call back into c during Put via fallback()
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker externally so it can pay sendValue
        vm.deal(address(attacker), attackerInitialBalance);

        // perform the deposit from attacker: attacker will call c.Put with value and attempt reentrancy
        // when successful (in reference) Put will record the full msg.value into Acc[attacker]
        attacker.doDeposit{value: sendValue}();

        // read recorded balance from c for the attacker address
        uint recorded = c.Acc(address(attacker)).balance;

        // The universal property: after the Put call completes, recorded balance must be >= the sent value.
        // (We assert equality to be stricter: since attacker had no prior balance, it should equal sent value)
        assertTrue(recorded >= sendValue);
    }
}

