pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: amount (sent with Put) and a boolean deciding whether the attacker will try reentrancy
    function testFuzz_property(uint256 amount, bool doReenter) public {
        // Keep domain wide but meaningful: amount must be non-zero and not exceed reasonable bound to avoid OOG
        amount = bound(amount, 0, 10 ether);
        vm.assume(amount > 0);

        // Deploy an attacker contract that will attempt reentrancy on receive()
        Attacker attacker = new Attacker(address(c));

        // Fund the attacker externally so it can call Put with value
        vm.deal(address(attacker), amount);

        // Ensure Put's MinSum is 1 ether; we need some runs both below and above MinSum
        // We allow fuzz to choose amounts; the property must hold for all amounts (including < MinSum)

        // If doReenter is true, instruct attacker to attempt reentrancy during Put
        attacker.setReenter(doReenter);

        // Perform the Put from attacker (external contract), sending `amount` wei
        // Note: Put is external payable and will invoke attacker.receive() if payable
        attacker.doPut{value: amount}();

        // Read the recorded balance for attacker from the contract's public mapping getter
        //Acc is public mapping (Acc(address) returns (uint unlockTime, uint balance)) in original contract
        // The auto-generated getter returns the struct elements; call to get balance is c.Acc(address).balance
        (, uint recordedBalance) = c.Acc(address(attacker));

        // The universal property (single assertion): after Put returns, the recorded balance must be >= amount if Put accepted value
        // More precisely: if amount was forwarded to contract (address(c).balance increased by at least amount during the call),
        // then reference contract prevents reentrant Collect from reducing the recorded balance below the amount just deposited.
        // We observe by asserting recordedBalance >= amount when amount >= 1 wei and attacker attempted reentrancy.
        // This assertion is satisfied by the reference (nonReentrant require prevents reentry) and violated by mutant for some inputs.
        assertTrue(recordedBalance >= amount);
    }
}

