pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // We fuzz the sender address and the sent amount. The property:
    // After a single Put call by any caller sending some ETH, the stored balance for that caller
    // must be at least as large as it was before the call (non-decreasing). The mutant removing
    // the require can allow a reentrant sequence during Put that results in a decrease.
    function testFuzz_property(address actor, uint256 value) public {
        // keep value in a reasonable wide domain but non-zero
        vm.assume(actor != address(0));
        value = bound(value, 0, 10 ether);

        // record previous balance (public getter Acc returns a struct's fields via solidity auto-getter)
        // Acc is mapping(address => Holder) public Acc; Holder has (uint unlockTime; uint balance;)
        uint256 before = c.Acc(actor).balance;

        // fund actor so they can send value
        vm.deal(actor, value);

        // perform Put as the actor; note: we do not enforce value >= MinSum here; property should hold for all inputs
        vm.prank(actor);
        try c.Put{value: value}(block.timestamp + 1) {
            // success
        } catch {
            // ignore reverts; property must still hold for successful calls in reference
        }

        uint256 after = c.Acc(actor).balance;

        // Single assertion: reference contract ensures balances never decrease through Put (nonReentrant prevents reentrant Collect during Put);
        // mutant that removes the require can cause after < before for some inputs (attacker reentrancy). This assert must pass on reference for all inputs,
        // and fail on mutant for some input (the fuzzer will find it).
        assertTrue(after >= before);
    }
}

